                    circles += amzp_alpha * normalize(v) * ((p2 - p1) / (2.0 * h) * (1.0 - t) * (1.0 - t));
                }
            }
            circles /= float((int(amzp_MAX_RADIUS)*2+1)*(int(amzp_MAX_RADIUS)*2+1));
            float intensity = mix(0.01, 0.15, smoothstep(0.1, 0.6, abs(fract(0.05*iTime + 0.5)*2.-1.0)));
            float3 n = float3(circles, sqrt(1.0 - dot(circles, circles)));
         float3 color = amzTexture(0, uv2/resolution - intensity*n.xy).rgb
         + 5.0*pow(clamp(dot(n,
         normalize(float3(1.0, 0.7, 0.5))), 0.0, 1.0), 6.0);
            fragColor = float4(color, 1.0);
     amzOutput = mix(texColor, fragColor, 1.0) * texColor.a;
          }
        }

